    {
      "rank": 1,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Hidetoshi Katori",
        "Jun Ye"
      ],
      "assessment": {
        "nobel_worthiness": "Optical lattice clocks made extraordinarily precise, stable timekeeping possible and opened new tests of fundamental physics. This is a major advance in atomic physics and precision measurement.",
        "attribution": "Katori and Ye independently developed leading optical lattice clock approaches and drove their experimental realization.",
        "maturity": "The methods have been repeatedly refined and adopted by multiple laboratories; their scientific impact is established.",
        "uncertainties": [
          "The broader development of optical clocks involved many groups, so the boundaries of individual credit require care."
        ]
      }
    },
    {
      "rank": 2,
      "ballot_id": "B008",
      "proposed_laureates": [
        "Alexei Kitaev",
        "Andrew M. Steane",
        "Peter W. Shor"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum error correction showed how quantum information can be protected despite decoherence, changing the understanding of what quantum computation can in principle achieve.",
        "attribution": "Shor and Steane introduced seminal quantum codes, while Kitaev developed influential topological approaches to fault tolerance.",
        "maturity": "The principles are well established, and error correction has been demonstrated across several platforms, although large-scale fault-tolerant computation remains a goal.",
        "uncertainties": [
          "The field has many important contributors, and the precise division of credit among foundational ideas is complex."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Michael V. Berry",
        "Yakir Aharonov"
      ],
      "assessment": {
        "nobel_worthiness": "The Aharonov–Bohm effect and Berry phase revealed that quantum phases can have observable consequences tied to global properties of fields and parameter space. These ideas now reach across physics.",
        "attribution": "Aharonov is central to the first effect, and Berry gave the geometric phase its influential general formulation.",
        "maturity": "Both effects have extensive experimental confirmation and have become standard concepts in quantum physics.",
        "uncertainties": [
          "The two contributions are related but distinct, and the historical antecedents and experimental development of each involve other physicists."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B020",
      "proposed_laureates": [
        "Juan Ignacio Cirac",
        "Peter Zoller",
        "Rainer Blatt"
      ],
      "assessment": {
        "nobel_worthiness": "Trapped ions turned quantum information processing into a concrete physical program, combining precise control of individual quantum systems with entangling interactions.",
        "attribution": "Cirac and Zoller established key theoretical foundations, while Blatt's experiments demonstrated and advanced the central operations.",
        "maturity": "The approach has been reproduced and developed by many laboratories, with sustained progress in control and error correction.",
        "uncertainties": [
          "The field's progress is collective, and the proposed trio represents foundational theory and experimental realization rather than all major contributions."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B001",
      "proposed_laureates": [
        "Charles L. Bennett",
        "David N. Spergel",
        "Lyman A. Page Jr."
      ],
      "assessment": {
        "nobel_worthiness": "WMAP's precision maps of the cosmic microwave background made cosmology a quantitative field, tightly constraining the age, composition, and evolution of the universe.",
        "attribution": "Bennett led the mission, Page led important instrument and analysis work, and Spergel made major contributions to the cosmological interpretation.",
        "maturity": "The results have been checked against later observations and remain foundational to modern cosmology.",
        "uncertainties": [
          "WMAP built on COBE's pioneering discovery and was followed by Planck, so the distinction between discovery and precision measurement matters for credit."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B025",
      "proposed_laureates": [
        "Charles L. Kane",
        "Eugene J. Mele",
        "Laurens W. Molenkamp"
      ],
      "assessment": {
        "nobel_worthiness": "The prediction and experimental realization of topological insulators established new phases of matter with robust boundary states and reshaped condensed matter physics.",
        "attribution": "Kane and Mele developed the influential theoretical predictions, and Molenkamp's experiments demonstrated the quantum spin Hall effect.",
        "maturity": "The phase has been confirmed in multiple materials and has generated a durable body of experimental and theoretical work.",
        "uncertainties": [
          "Many groups contributed to the wider discovery and characterization of topological materials, so the selected contribution must be defined narrowly."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B037",
      "proposed_laureates": [
        "Christopher Jarzynski",
        "Denis J. Evans",
        "Gavin E. Crooks",
        "Udo Seifert"
      ],
      "assessment": {
        "nobel_worthiness": "Fluctuation theorems and stochastic thermodynamics extended thermodynamic laws to small, fluctuating systems, connecting statistical mechanics with experiments on individual nanoscale systems.",
        "attribution": "These four made distinct foundational contributions to the theory and its development into a coherent framework.",
        "maturity": "The relations have been tested in a variety of systems and are now widely used in nonequilibrium statistical physics.",
        "uncertainties": [
          "The foundational results emerged across several groups, making credit allocation difficult within the three-person laureate limit."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B050",
      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry uses matter-wave coherence for exceptionally sensitive measurements, extending quantum interference methods into precision tests of gravity and fundamental constants.",
        "attribution": "Bordé, Pritchard, and Kasevich made important contributions to the development and experimental use of atom interferometers.",
        "maturity": "The technique has been demonstrated and refined across many laboratories and measurement settings.",
        "uncertainties": [
          "Atom interferometry developed through a broad sequence of contributions, and the specific boundaries of a prize-worthy discovery are not as sharp as for a single landmark result."
        ]
      }
    }
  ]
}
